// Title: Yonut 001
// Author: Claude, ItsWesSmithYo
// Project: OneManShYo

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates to range (-1.0, 1.0) and maintain aspect ratio
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Calculate the distance from the center
    float radius = length(uv) * 6.0; // Scale for more circles

    // Time-based pulsing animation
    float t = iTime * 2.0; // Speed of pulsing
    float wave = sin(radius - t) * 0.5 + 0.5; // Oscillating brightness

    // Define the color based on the wave
    vec3 color = vec3(0.2, wave, wave * 0.8); // Cyan tones with smooth pulsation

    // Add a subtle vignette effect
    float vignette = smoothstep(1.5, 0.5, length(uv));
    fragColor = vec4(color * vignette, 1.0);
}
